const expandedItems = [...(context.component.variables['expandedFaqItems'] || [])];
const itemIndex = expandedItems.indexOf(context.parameters['itemId']);

if (itemIndex > -1) {
  // Item is expanded, collapse it
  expandedItems.splice(itemIndex, 1);
} else {
  // Item is collapsed, expand it
  expandedItems.push(context.parameters['itemId']);
}

context.component.variables['expandedFaqItems'] = expandedItems;
